import { Interactive, Sequence, random, useCurrentFrame, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import { forwardRef, useImperativeHandle, useRef, type ComponentProps } from "react";

interface RGBGlitchTextProps {
  text: string;
  fontSize?: number;
  color?: string;
  fontWeight?: number;
  glitchAt?: number;
  glitchDuration?: number;
  intensity?: number;
  seed?: string;
  speed?: number;
  className?: string;
}

function RGBGlitchTextBase({
  text,
  fontSize = 96,
  color = "#171717",
  fontWeight = 700,
  glitchAt = 20,
  glitchDuration = 8,
  intensity = 6,
  seed = "glitch",
  speed = 1,
  className,
}: RGBGlitchTextProps) {
  const frame = useCurrentFrame() * speed;

  const isGlitching = frame >= glitchAt && frame < glitchAt + glitchDuration;

  const offset = (axisSeed: string, scale: number) =>
    (random(`${seed}-${axisSeed}-${frame}`) * 2 - 1) * scale;

  const rX = isGlitching ? offset("r-x", intensity) : 0;
  const rY = isGlitching ? offset("r-y", intensity * 0.4) : 0;
  const gX = isGlitching ? offset("g-x", intensity) : 0;
  const gY = isGlitching ? offset("g-y", intensity * 0.4) : 0;
  const bX = isGlitching ? offset("b-x", intensity) : 0;
  const bY = isGlitching ? offset("b-y", intensity * 0.4) : 0;

  const copyOpacity = isGlitching ? 1 : 0;

  const baseStyle: React.CSSProperties = {
    position: "absolute",
    top: 0,
    left: 0,
    fontSize,
    fontWeight,
    letterSpacing: "-0.03em",
    fontFamily:
      "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif",
    whiteSpace: "pre",
    mixBlendMode: "multiply",
  };

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: "#fafafa",
      }}
    >
      <div
        className={className}
        style={{ position: "relative", display: "inline-block" }}
      >
        <span
          style={{
            position: "relative",
            fontSize,
            fontWeight,
            color,
            letterSpacing: "-0.03em",
            fontFamily:
              "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif",
            whiteSpace: "pre",
          }}
        >
          {text}
        </span>
        <span
          style={{
            ...baseStyle,
            color: "#ff0040",
            opacity: copyOpacity,
            translate: `${rX}px ${rY}px`,
          }}
        >
          {text}
        </span>
        <span
          style={{
            ...baseStyle,
            color: "#00ff80",
            opacity: copyOpacity,
            translate: `${gX}px ${gY}px`,
          }}
        >
          {text}
        </span>
        <span
          style={{
            ...baseStyle,
            color: "#0080ff",
            opacity: copyOpacity,
            translate: `${bX}px ${bY}px`,
          }}
        >
          {text}
        </span>
      </div>
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  text: {
    type: "text-content",
    default: "GLITCH",
    description: "Text",
  },
  fontSize: {
    type: "number",
    min: 12,
    max: 200,
    step: 1,
    default: 96,
    description: "Font size",
    hiddenFromList: false,
  },
  color: {
    type: "color",
    default: "#171717",
    description: "Color",
  },
  fontWeight: {
    type: "enum",
    default: "700",
    variants: {
      "400": {},
      "500": {},
      "600": {},
      "700": {},
    },
    description: "Font weight",
  },
  glitchAt: {
    type: "number",
    min: 0,
    max: 120,
    step: 1,
    default: 20,
    description: "Glitch at (frame)",
    hiddenFromList: false,
  },
  glitchDuration: {
    type: "number",
    min: 1,
    max: 60,
    step: 1,
    default: 8,
    description: "Glitch duration",
    hiddenFromList: false,
  },
  intensity: {
    type: "number",
    min: 0,
    max: 30,
    step: 1,
    default: 6,
    description: "Intensity (px)",
    hiddenFromList: false,
  },
  seed: {
    type: "text-content",
    default: "glitch",
    description: "Seed",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  width: {
    type: "number",
    default: 300,
    min: 10,
    step: 10,
    description: "Width",
  },
  height: {
    type: "number",
    default: 130,
    min: 10,
    step: 10,
    description: "Height",
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["text","fontSize","color","fontWeight","glitchAt","glitchDuration","intensity","seed","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  text: "GLITCH",
  fontSize: 96,
  color: "#171717",
  fontWeight: "700",
  glitchAt: 20,
  glitchDuration: 8,
  intensity: 6,
  seed: "glitch",
  speed: 1,
};

type RGBGlitchTextElementProps = InteractiveBaseProps &
  InteractiveTransformProps & { readonly width?: number; readonly height?: number } &
  ComponentProps<typeof RGBGlitchTextBase>;

const RGBGlitchTextInner = forwardRef<
  HTMLDivElement,
  RGBGlitchTextElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, width = 300, height = 130, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<RGBGlitchText>"}
      outlineRef={outlineRef}
    >
      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div
          ref={outlineRef}
          style={{
            position: "relative",
            width,
            height,
            ...style,
          }}
        >
          <RGBGlitchTextBase
            {...(componentProps as unknown as ComponentProps<typeof RGBGlitchTextBase>)}
          />
        </div>
      </div>
    </Sequence>
  );
});

export const RGBGlitchText = Interactive.withSchema({
  Component: RGBGlitchTextInner,
  componentName: "<RGBGlitchText>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
